const state=JSON.parse(localStorage.getItem('medchemState')||'{}');Object.assign(state,{done:state.done||[],bookmarks:state.bookmarks||[],notes:state.notes||{},recent:state.recent||[],quiz:state.quiz||[],theme:state.theme||'dark'});let view='home',activeSlide=null,filter='all',searchTerm='',quizSet=[],quizIndex=0,quizAnswers={},quizSubmitted=false,simStep=0;
const app=document.getElementById('app');function save(){localStorage.setItem('medchemState',JSON.stringify(state))}function toast(t){let el=document.getElementById('toast');el.textContent=t;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),1800)}function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function pct(){return Math.round(state.done.length/33*100)}function setView(v){view=v;activeSlide=null;document.querySelectorAll('.tab').forEach(b=>b.classList.toggle('active',b.dataset.view===v));render()}function slideBy(n){return slides.find(s=>s.n===n)}function openSlide(n){activeSlide=n;state.recent=[n,...state.recent.filter(x=>x!==n)].slice(0,5);save();render()}function moduleFor(id){return modules.find(m=>m[0]===id)}
function home(){let recent=state.recent.map(slideBy).filter(Boolean);return `<section class="hero"><div class="eyebrow">MEDICINAL CHEMISTRY · CHAPTER 01</div><h1>Sulfonamides<span style="color:var(--teal)">.</span></h1><p>Explore the chemistry, mechanism, SAR and clinical relevance of sulfonamide antibacterials — one interactive concept at a time.</p><div class="hero-meta"><span class="chip">33 original slides</span><span class="chip">8 learning modules</span><span class="chip">Source-linked learning</span></div><button class="primary" onclick="setView('library')">Continue learning&nbsp; →</button></section><div class="section-head"><div><h2>Your learning dashboard</h2><p>Progress is saved on this device</p></div></div><div class="grid"><div class="stat"><strong class="accent">${pct()}%</strong><span>Chapter progress</span><div class="progress"><span style="width:${pct()}%"></span></div></div><div class="stat"><strong>${state.done.length}<small class="muted"> / 33</small></strong><span>Slides completed</span></div><div class="stat"><strong>${state.bookmarks.length}</strong><span>Bookmarked slides</span></div><div class="stat"><strong>${state.quiz.length}</strong><span>Quiz attempts</span></div></div><div class="section-head"><div><h2>Learning modules</h2><p>Original slide sequence preserved</p></div></div><div class="module-grid">${modules.map(m=>`<div class="module-card" onclick="filterModule('${m[0]}')"><div class="module-icon">${m[2]}</div><h3>${m[0]}</h3><p>${m[1]}</p><small>${m[3].length} slides · Explore →</small></div>`).join('')}</div><div class="section-head"><div><h2>Recently studied</h2><p>Pick up where you left off</p></div></div>${recent.length?`<div class="slide-list">${recent.map(s=>slideRow(s)).join('')}</div>`:'<div class="card muted small">Your recently opened slides will appear here.</div>'}<div class="section-head"><div><h2>Daily revision challenge</h2><p>Quick recall from the uploaded lecture</p></div></div><div class="card"><b>Why can N-acetylation of sulfonamides cause renal problems?</b><p class="small muted">Think about hydrophobicity and aqueous solubility before revealing the answer.</p><button class="secondary" onclick="this.nextElementSibling.hidden=!this.nextElementSibling.hidden">Reveal explanation</button><p hidden class="small">Slide 26: N-acetylation increases hydrophobic character and reduces aqueous solubility; the slide links this to an insoluble metabolite and renal tubule blockage.</p></div>`}
function slideRow(s){return `<div class="slide-card" onclick="openSlide(${s.n})"><div class="slide-no">${String(s.n).padStart(2,'0')}</div><div class="slide-info"><b>${esc(s.title)}</b><small>${esc(s.concept)}</small></div><div class="slide-status">${state.done.includes(s.n)?'✓':state.bookmarks.includes(s.n)?'◆':'›'}</div></div>`}
function filterModule(name){searchTerm='';filter=name;setView('library')}
function library(){let list=slides.filter(s=>(filter==='all'||s.module===filter)&&(`${s.n} ${s.title} ${s.concept} ${s.content} ${s.terms}`).toLowerCase().includes(searchTerm.toLowerCase()));return `<div class="eyebrow">CHAPTER LIBRARY</div><h1 style="font-size:28px;margin:8px 0">All 33 slides</h1><p class="muted small">Every original slide is represented in sequence. Image-only or unclear slides are flagged.</p><div class="toolbar"><input class="search" placeholder="Search drug, mechanism, term or slide…" value="${esc(searchTerm)}" oninput="searchTerm=this.value;render()"><select onchange="filter=this.value;render()"><option value="all">All modules</option>${modules.map(m=>`<option value="${m[0]}" ${filter===m[0]?'selected':''}>${m[0]}</option>`).join('')}</select><select onchange="filterStatus(this.value)"><option value="any">All status</option><option value="done">Completed</option><option value="todo">Not completed</option><option value="saved">Bookmarked</option></select></div><div class="slide-list">${list.map(slideRow).join('')||'<div class="empty">No slides match your search.</div>'}</div><p class="muted small" style="text-align:center;margin-top:18px">Showing ${list.length} of 33 slides · Original slide numbers retained</p>`}
function filterStatus(v){if(v==='any'){searchTerm='';filter='all';render();return}let arr=v==='done'?state.done:v==='todo'?slides.filter(s=>!state.done.includes(s.n)).map(s=>s.n):state.bookmarks;searchTerm='';let ids=new Set(arr);document.querySelectorAll('.slide-card').forEach(e=>e.style.display='none');let target=slides.filter(s=>ids.has(s.n));app.querySelector('.slide-list').innerHTML=target.map(slideRow).join('')||'<div class="empty">No slides in this category yet.</div>'}
function slideDetail(s){let done=state.done.includes(s.n),book=state.bookmarks.includes(s.n);return `<div class="backline"><button onclick="activeSlide=null;render()">← All slides</button><span class="muted small">SLIDE ${s.n} / 33</span></div><div class="eyebrow">${modules.find(m=>m[3].includes(s.n))?.[0]||'CHAPTER'}</div><h1 class="slide-title">${esc(s.title)}</h1><p class="muted small">${esc(s.concept)}</p><div class="slide-actions"><button class="${done?'secondary':'primary'}" onclick="toggleDone(${s.n})">${done?'✓ Completed':'Mark complete'}</button><button class="ghost" onclick="toggleBookmark(${s.n})">${book?'◆ Bookmarked':'◇ Bookmark'}</button></div><div class="content-card"><div class="source-label">Original lecture content · Slide ${s.n}</div><p>${esc(s.content)}</p><div class="source-label" style="margin-top:15px">Important terms</div><p>${esc(s.terms)}</p></div><div class="content-card"><div class="source-label extra-label">Study guidance</div><p>${esc(s.note)}</p><p class="small muted">This note distinguishes source limitations; it does not add unverified lecture facts.</p></div><div class="content-card"><h3>Personal notes</h3><textarea class="note" placeholder="Write your own notes for slide ${s.n}…" oninput="state.notes[${s.n}]=this.value;save()">${esc(state.notes[s.n]||'')}</textarea></div><div class="stepper"><button class="ghost" ${s.n===1?'disabled':''} onclick="openSlide(${s.n-1})">← Previous</button><span class="muted small">${s.n} of 33</span><button class="secondary" ${s.n===33?'disabled':''} onclick="openSlide(${s.n+1})">Next →</button></div>`}
function studio(){return `<div class="eyebrow">MEDICINAL CHEMISTRY LEARNING STUDIO</div><h1 style="font-size:28px;margin:8px 0">Explore the science</h1><p class="muted small">Interactive teaching models based on concepts actually present in this chapter.</p><div class="module-grid"><div class="module-card" onclick="sim('ion')"><div class="module-icon">⚗</div><h3>pKa & ionization lab</h3><p>Explore weak-acid ionization across pH.</p><small>Henderson–Hasselbalch →</small></div><div class="module-card" onclick="sim('folate')"><div class="module-icon">⇢</div><h3>Folate pathway explorer</h3><p>Step through DHPS and DHFR blockade.</p><small>Mechanism simulator →</small></div><div class="module-card" onclick="sim('sar')"><div class="module-icon">⌘</div><h3>SAR explorer</h3><p>Review essential structural features from slide 24.</p><small>Pharmacophore →</small></div><div class="module-card molecule-launch" onclick="sim('molecule')"><div class="module-icon">🧬</div><h3>3D Molecular Lab</h3><p>Rotate real 3D conformers and inspect highlighted pharmacophore and R groups.</p><small>Open molecular lab →</small></div><div class="module-card" onclick="sim('met')"><div class="module-icon">⇄</div><h3>N-acetylation explorer</h3><p>Follow the lecture’s metabolism-to-solubility link.</p><small>Metabolism →</small></div><div class="module-card" onclick="sim('compare')"><div class="module-icon">⊞</div><h3>Drug comparison</h3><p>Compare lecture-mentioned agents and uses.</p><small>Compare →</small></div><div class="module-card" onclick="sim('binding')"><div class="module-icon">⚛</div><h3>Binding interactions</h3><p>Inspect the interaction types named in slide 18.</p><small>Interaction map →</small></div></div><div class="callout" style="margin-top:16px">Scientific boundary: the pKa lab is a mathematical teaching model. It does not predict measured solubility, antibacterial potency or clinical outcomes.</div>`}
function sim(type){view='studio';let html='';if(type==='ion'){html=`<div class="backline"><button onclick="render()">← Studio</button></div><div class="eyebrow">INTERACTIVE SIMULATOR</div><h1 class="slide-title">pKa & ionization explorer</h1><p class="muted small">Weak-acid model · connected to slides 18–22</p><div class="content-card sim-controls"><label>pH <b id="phVal">7.4</b></label><input id="ph" type="range" min="1" max="14" step="0.1" value="7.4" oninput="calcIon()"><label>pKa <b id="pkaVal">5.0</b></label><input id="pka" type="range" min="2" max="12" step="0.1" value="5" oninput="calcIon()"><div class="equation">% ionized = 100 / (1 + 10<sup>(pKa − pH)</sup>)</div><div class="result" id="ionResult">99.6%</div><span class="muted small">Calculated ionized fraction for a monoprotic weak acid</span><div class="progress"><span id="ionBar" style="width:99.6%"></span></div><p id="ionInterpret" class="small">At pH above pKa, the weak acid is predominantly ionized.</p><button class="ghost" onclick="document.getElementById('ph').value=7.4;document.getElementById('pka').value=5;calcIon()">Reset values</button></div><div class="content-card"><h3>Variables & interpretation</h3><p>pH = environmental acidity; pKa = acid dissociation constant expressed as pKa. This calculation describes the equilibrium fraction only. It does not itself calculate solubility or permeability.</p><div class="callout">Lecture connection: slides 21–22 discuss a balance between nonionized drug (more lipid soluble) and ionized drug (more water soluble), alongside crystalluria.</div></div><div class="content-card"><h3>Quick challenge</h3><p>For a weak acid, what happens to the ionized fraction when pH rises above pKa?</p><button class="secondary" onclick="toast('It increases — the weak acid becomes more ionized.')">Check answer</button></div>`}
if(type==='folate'){let names=['PABA + dihydroneopterin diphosphate','Dihydropteroate synthase (DHPS)','Dihydrofolic acid','Dihydrofolate reductase (DHFR)','Tetrahydrofolic acid → thymidine / DNA'];let desc=['The lecture pathway starts with PABA and dihydroneopterin diphosphate.','Sulfonamides compete at the PABA-utilizing DHPS step; slide 11 depicts a false metabolite.','Dihydrofolic acid is the substrate shown upstream of DHFR.','Trimethoprim inhibits DHFR in the slide 30 pathway.','Tetrahydrofolic acid is downstream and linked in the diagram to thymidine and DNA.'];html=`<div class="backline"><button onclick="render()">← Studio</button></div><div class="eyebrow">MECHANISM EXPLORER · SLIDES 11, 30–32</div><h1 class="slide-title">Microbial folate pathway</h1><div class="content-card"><div class="stepper" id="folSteps">${names.map((n,i)=>`<div class="step ${i===0?'active':''}" onclick="setFolate(${i})">${i+1}</div>`).join('')}</div><h3 id="folTitle" style="margin-top:18px">${names[0]}</h3><p id="folDesc">${desc[0]}</p><div class="equation">${names[0]} → folate pathway → THF</div><div class="stepper"><button class="ghost" onclick="setFolate(Math.max(0,simStep-1))">Previous</button><span id="folCount" class="muted small">Step 1 / 5</span><button class="secondary" onclick="setFolate(Math.min(4,simStep+1))">Next</button></div></div><div class="callout">Sulfonamide blockade: DHPS. Trimethoprim blockade: DHFR. The combined sequential blockade is summarized on slide 32.</div>`;window._folNames=names;window._folDesc=desc;simStep=0}
if(type==='sar'){html=`<div class="backline"><button onclick="render()">← Studio</button></div><div class="eyebrow">SAR EXPLORER · SLIDE 24</div><h1 class="slide-title">Sulfonamide pharmacophore</h1><div class="content-card"><svg class="molecule" viewBox="0 0 520 180" role="img" aria-label="Schematic para-aminobenzenesulfonamide scaffold"><rect x="20" y="20" width="480" height="140" rx="12" fill="#f5f7f6"/><polygon points="170,48 220,48 245,90 220,132 170,132 145,90" fill="none" stroke="#234" stroke-width="3"/><text x="108" y="94" fill="#147a9a" font-size="18" font-weight="bold">H₂N</text><line x1="145" y1="90" x2="95" y2="90" stroke="#234" stroke-width="3"/><line x1="245" y1="90" x2="300" y2="90" stroke="#234" stroke-width="3"/><text x="305" y="96" fill="#a46b16" font-size="20" font-weight="bold">SO₂–NHR</text><text x="165" y="28" fill="#147a9a" font-size="12">Aromatic ring</text><text x="45" y="145" fill="#147a9a" font-size="12">N4</text><text x="390" y="145" fill="#a46b16" font-size="12">N1</text></svg><div class="callout">Schematic scaffold only — not an atom-perfect molecular structure or a rotatable 3D model.</div><ul><li><b>N4:</b> essential for activity; must be unsubstituted.</li><li><b>Aromatic ring:</b> essential; para-substituted only.</li><li><b>Sulfonamide:</b> essential; N1 nitrogen must be secondary.</li><li><b>R1 acyl:</b> allowed; slide says inactive in vitro, active in vivo.</li><li><b>Varying R:</b> can affect solubility and plasma protein binding.</li></ul></div><div class="content-card"><h3>Tap a feature to review</h3><div class="toolbar"><button class="secondary" onclick="toast('N4: essential and must be unsubstituted — slide 24.')">N4</button><button class="secondary" onclick="toast('Aromatic ring: essential and para-substituted only — slide 24.')">Aromatic ring</button><button class="secondary" onclick="toast('N1: sulfonamide nitrogen must be secondary — slide 24.')">N1</button><button class="secondary" onclick="toast('R variation affects solubility and plasma protein binding — slide 24.')">R group</button></div></div>`}
if(type==='molecule'){html=`<div class="backline"><button onclick="render()">← Studio</button></div><div class="eyebrow">MOLECULAR EXPLORATION · 3D + SAR</div><h1 class="slide-title">Interactive molecular lab</h1><p class="muted small">Rotate, zoom and inspect lecture-related molecules. Teal marks the shared sulfanilamide pharmacophore; gold marks the variable substituent where the lecture scaffold match applies.</p><div class="content-card"><label class="mol-label" for="molSelect">Choose a documented molecule</label><select id="molSelect" class="mol-select" onchange="loadMolecule(this.value)"><option value="sulfanilamide">Sulfanilamide · parent scaffold</option><option value="sulfathiazole">Sulfathiazole</option><option value="sulfamethoxazole" selected>Sulfamethoxazole</option><option value="sulfisoxazole">Sulfisoxazole</option><option value="sulfadiazine">Sulfadiazine</option><option value="sulfacetamide">Sulfacetamide</option><option value="sulfapyridine">Sulfapyridine</option><option value="trimethoprim">Trimethoprim · separate DHFR inhibitor</option></select><div class="mol-facts"><div><small>Selected compound</small><b id="molName">Sulfamethoxazole</b></div><div><small>Formula</small><b id="molFormula">—</b></div><div><small>Molecular weight</small><b id="molMW">—</b></div></div><div class="mol-viewer-wrap"><div id="mol3d" class="mol3d"><div class="mol-loading">Loading 3D conformer…</div></div><div class="mol-controls"><button class="secondary" onclick="setMolStyle('stick')">Stick</button><button class="secondary" onclick="setMolStyle('ball')">Ball & stick</button><button class="secondary" onclick="resetMolView()">Reset view</button><button class="ghost" onclick="toggleMolSpin()" id="molSpinBtn">Pause rotation</button></div></div><div class="mol-legend"><span><i class="legend-dot teal"></i> Shared pharmacophore</span><span><i class="legend-dot gold"></i> Variable substituent (R)</span><span><i class="legend-dot grey"></i> Other atoms / separate scaffold</span></div><div class="mol-note" id="molNote">Loading compound information…</div><div class="mol-sar-effect" id="molSarEffect"><b>Substituent effect from the lecture</b><p>Loading slide-linked SAR notes…</p></div></div><div class="content-card"><div class="source-label">2D atom-group map</div><h3>Color-coded chemical structure</h3><img id="mol2d" class="mol2d" alt="Color-coded 2D chemical structure"><p class="small muted">The 2D map highlights the shared para-aminobenzenesulfonamide pharmacophore in teal and the remaining substituent in gold. For trimethoprim, which is not a sulfonamide, the separate scaffold is shown in grey.</p></div><div class="content-card"><div class="source-label">SAR modification navigator · lecture slides 19, 24, 27, 29</div><h3>Explore named lecture analogues</h3><p class="small muted">Choose a known structure to see its actual name and structure. This is a curated analogue selector, not a reaction predictor: the app will not invent a drug name for an unverified substituent.</p><div class="sar-picks"><button onclick="loadMolecule('sulfanilamide')"><b>Parent</b><small>Sulfanilamide</small></button><button onclick="loadMolecule('sulfathiazole')"><b>Thiazolyl</b><small>Sulfathiazole</small></button><button onclick="loadMolecule('sulfamethoxazole')"><b>Methylisoxazolyl</b><small>Sulfamethoxazole</small></button><button onclick="loadMolecule('sulfisoxazole')"><b>Dimethylisoxazolyl</b><small>Sulfisoxazole</small></button><button onclick="loadMolecule('sulfadiazine')"><b>Pyrimidinyl</b><small>Sulfadiazine</small></button><button onclick="loadMolecule('sulfacetamide')"><b>Acetyl</b><small>Sulfacetamide</small></button><button onclick="loadMolecule('sulfapyridine')"><b>Pyridyl</b><small>Sulfapyridine</small></button></div><div class="callout"><b>Lecture SAR (slide 24):</b> aromatic ring essential and para-substituted only; N4 essential and unsubstituted; sulfonamide essential and N1 must be secondary. The slide states R variation can affect solubility and plasma protein binding. It does not provide numerical activity predictions for arbitrary substitutions.</div></div><div class="content-card"><h3>What this 3D view represents</h3><p class="small">These are computational 3D conformers generated from curated molecular SMILES and energy-minimized for visualization. They are rotatable molecular models, but they are not experimentally solved crystal structures, protein-bound poses, or predictions of binding affinity. Atom-group colors are a teaching overlay.</p><p class="small muted">Structure identifiers and molecular descriptors are attributed to PubChem records; conformers generated locally with RDKit ETKDG and force-field minimization.</p></div>`}
if(type==='met'){html=`<div class="backline"><button onclick="render()">← Studio</button></div><div class="eyebrow">METABOLISM EXPLORER · SLIDE 26</div><h1 class="slide-title">N-acetylation consequence chain</h1><div class="content-card"><div class="stepper"><div class="step active">Sulfathiazole</div><div class="step">N-acetylation</div><div class="step">Insoluble metabolite</div></div><p>Lecture sequence: sulfathiazole → N-acetylation → increased hydrophobic character → reduced aqueous solubility → possible renal tubule blockage.</p><div class="callout">The slide names renal tubule blockage as the possible toxic side effect. This is a conceptual sequence, not a quantitative metabolic simulation.</div></div><div class="content-card"><h3>Other pharmacokinetic statements on slide 26</h3><ul><li>Orally administered sulfonamides are well absorbed from the GI tract.</li><li>Distributed fairly widely and excreted by the kidney.</li><li>Bound to plasma protein and may displace other protein-bound drugs and bilirubin.</li><li>Not used in late-term pregnancy according to the slide, due to possible neonatal jaundice.</li></ul></div>`}
if(type==='compare'){html=`<div class="backline"><button onclick="render()">← Studio</button></div><div class="eyebrow">DRUG COMPARISON · SLIDES 27–33</div><h1 class="slide-title">Lecture drug directory</h1><div class="content-card table-wrap"><table><thead><tr><th>Drug</th><th>Lecture detail</th><th>Slide</th></tr></thead><tbody><tr><td>Sulfisoxazole</td><td>pKa approximately 5.0 (slides 19, 22); shown as an example sulfonamide.</td><td>19, 22, 27</td></tr><tr><td>Sulfamethoxazole</td><td>Shown as a current agent and in TMP-SMX combination.</td><td>14, 27, 32–33</td></tr><tr><td>Sulfadiazine</td><td>Topical use for treatment of burns.</td><td>19, 27</td></tr><tr><td>Sulfacetamide</td><td>Ophthalmic use for eye infections; salt/high water solubility discussion.</td><td>27</td></tr><tr><td>Sulfadoxine</td><td>Long-acting; once-weekly dosing regime; very high protein binding.</td><td>27</td></tr><tr><td>Trimethoprim</td><td>DHFR inhibitor; bacterial enzyme stated to be 100,000 times more sensitive.</td><td>30–32</td></tr><tr><td>Sulfasalazine</td><td>Gut cleavage to mesalamine and sulfapyridine.</td><td>29</td></tr></tbody></table></div><p class="muted small">Only lecture-supported details are populated. Missing properties such as exact molecular weights or logP are intentionally omitted.</p>`}
if(type==='binding'){html=`<div class="backline"><button onclick="render()">← Studio</button></div><div class="eyebrow">BINDING INTERACTIONS · SLIDE 18</div><h1 class="slide-title">Molecular interaction map</h1><div class="content-card"><h3>Interaction types named in the lecture</h3><div class="module-grid"><div class="tool-card"><b style="color:var(--teal)">H-bond</b><p class="small muted">Hydrogen-bond interaction</p></div><div class="tool-card"><b style="color:var(--cyan)">van der Waals</b><p class="small muted">van der Waals interactions</p></div><div class="tool-card"><b style="color:var(--gold)">Ionic bond</b><p class="small muted">Ionic interaction</p></div></div><p>Slide 18 shows active-site interaction illustrations and asks the student to identify inhibition type and how potency could be enhanced. It labels pKa values 4.9 and 10.4.</p><div class="callout">The slide does not provide a written answer to its question. No inhibition classification or potency enhancement rule is asserted here.</div></div>`}
app.innerHTML=html;if(type==='molecule')loadMolecule('sulfamethoxazole');}
let molViewer=null,molCurrent='sulfamethoxazole',molManifest=null,molSpinning=true,molStyle='stick';
async function loadMolecule(id){molCurrent=id;const sel=document.getElementById('molSelect');if(sel)sel.value=id;const name=document.getElementById('molName');if(name)name.textContent=id==='trimethoprim'?'Trimethoprim':id.charAt(0).toUpperCase()+id.slice(1);const note=document.getElementById('molNote');if(note)note.textContent='Loading curated structure…';try{if(!molManifest)molManifest=window.MOL_DATA||{};const m=molManifest[id];if(!m)throw Error('No structure record');document.getElementById('molName').textContent=m.name;document.getElementById('molFormula').textContent=m.formula;document.getElementById('molMW').textContent=m.mw.toFixed(2)+' g/mol';document.getElementById('molNote').textContent=m.note+' '+(m.has_core_match?'Teal = para-aminobenzenesulfonamide core; gold = remaining R substituent.':'This compound is a separate molecular scaffold; no sulfonamide pharmacophore is highlighted.');document.getElementById('molSarEffect').innerHTML='<b>Substituent / structural effect supported by the lecture</b><p>'+m.sar_effect+'</p><small>'+m.sar_source+'</small>';document.getElementById('mol2d').src='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(m.svg);const sdf=m.sdf;if(!window.$3Dmol){document.getElementById('mol3d').innerHTML='<div class="mol-loading">3D engine did not load. Connect to the internet and reload this page.</div>';return}const el=document.getElementById('mol3d');el.innerHTML='';molViewer=$3Dmol.createViewer(el,{backgroundColor:'#071827',antialias:true});molViewer.addModel(sdf,'sdf');applyMolStyle();molViewer.zoomTo();molViewer.render();molViewer.spin('y',1); }catch(e){const box=document.getElementById('mol3d');if(box)box.innerHTML='<div class="mol-loading">Could not load this molecular model. Check connection and refresh.</div>';if(note)note.textContent='Structure loading error: '+e.message;}}
function applyMolStyle(){if(!molViewer||!molManifest)return;const m=molManifest[molCurrent];const base=molStyle==='ball'?{stick:{radius:0.12,colorscheme:'Jmol'},sphere:{scale:0.24,colorscheme:'Jmol'}}:{stick:{radius:0.18,colorscheme:'Jmol'}};molViewer.setStyle({},base);if(m.has_core_match){m.pharmacophore_atoms.forEach(i=>molViewer.setStyle({index:i},{stick:{color:'#39d7c5',radius:0.22},sphere:{color:'#39d7c5',scale:0.29}}));m.variable_atoms.forEach(i=>molViewer.setStyle({index:i},{stick:{color:'#efbd58',radius:0.22},sphere:{color:'#efbd58',scale:0.29}}));}else{molViewer.setStyle({}, {stick:{color:'#9aaab5',radius:0.19},sphere:{color:'#9aaab5',scale:0.26}});}molViewer.render();}
function setMolStyle(s){molStyle=s;applyMolStyle()}function resetMolView(){if(molViewer){molViewer.zoomTo();molViewer.rotate(0,'y');molViewer.render()}}function toggleMolSpin(){molSpinning=!molSpinning;if(molViewer)molViewer.spin('y',1);const b=document.getElementById('molSpinBtn');if(b)b.textContent=molSpinning?'Pause rotation':'Start rotation'}
function calcIon(){let ph=+document.getElementById('ph').value,pka=+document.getElementById('pka').value,f=100/(1+Math.pow(10,pka-ph));document.getElementById('phVal').textContent=ph.toFixed(1);document.getElementById('pkaVal').textContent=pka.toFixed(1);document.getElementById('ionResult').textContent=f.toFixed(1)+'%';document.getElementById('ionBar').style.width=f+'%';document.getElementById('ionInterpret').textContent=ph>pka?'At pH above pKa, the weak acid is predominantly ionized.':ph<pka?'At pH below pKa, the weak acid is predominantly nonionized.':'At pH = pKa, the weak acid is 50% ionized.'}
function setFolate(i){simStep=i;document.querySelectorAll('#folSteps .step').forEach((e,j)=>e.classList.toggle('active',j===i));document.getElementById('folTitle').textContent=window._folNames[i];document.getElementById('folDesc').textContent=window._folDesc[i];document.getElementById('folCount').textContent=`Step ${i+1} / 5`}
function exam(){return `<div class="eyebrow">EXAM PREPARATION CENTER</div><h1 style="font-size:28px;margin:8px 0">Test your understanding</h1><p class="muted small">12 source-linked MCQs · randomized selection · immediate explanations</p><div class="grid"><div class="stat"><strong>${state.quiz.length}</strong><span>Completed attempts</span></div><div class="stat"><strong>${state.quiz.length?Math.round(state.quiz.reduce((a,b)=>a+b.score,0)/state.quiz.length)+'%':'—'}</strong><span>Average score</span></div></div><div class="content-card"><h3>Start an exam</h3><p class="small muted">Choose the number of questions. Each answer includes a slide reference.</p><select id="quizCount"><option value="5">5 questions · Quick test</option><option value="10">10 questions · Practice</option><option value="12">12 questions · Full bank</option></select><button class="primary" style="margin-left:8px" onclick="startQuiz()">Start exam →</button></div>${state.quiz.length?`<div class="content-card"><h3>Recent performance</h3>${state.quiz.slice(-5).reverse().map(q=>`<p class="small">${q.date} · <b>${q.score}%</b> (${q.correct}/${q.total})</p>`).join('')}</div>`:''}`}
function startQuiz(){let count=+document.getElementById('quizCount').value;quizSet=[...quizzes].sort(()=>Math.random()-.5).slice(0,count);quizIndex=0;quizAnswers={};quizSubmitted=false;renderQuiz()}
function renderQuiz(){let q=quizSet[quizIndex];app.innerHTML=`<div class="backline"><button onclick="setView('exam')">← Exit exam</button><span class="muted small">QUESTION ${quizIndex+1} / ${quizSet.length}</span></div><div class="progress"><span style="width:${(quizIndex+1)/quizSet.length*100}%"></span></div><h1 style="font-size:22px;line-height:1.3;margin:20px 0">${esc(q.q)}</h1><div class="content-card">${q.o.map((o,i)=>`<button class="quiz-option ${quizAnswers[quizIndex]===i?'selected':''}" onclick="chooseAnswer(${i})">${String.fromCharCode(65+i)}. ${esc(o)}</button>`).join('')}</div><div class="stepper"><button class="ghost" onclick="quizIndex=Math.max(0,quizIndex-1);renderQuiz()" ${quizIndex===0?'disabled':''}>Previous</button><button class="primary" onclick="nextQuestion()">${quizIndex===quizSet.length-1?'Submit exam':'Next question'}</button></div>`}
function chooseAnswer(i){quizAnswers[quizIndex]=i;renderQuiz()}function nextQuestion(){if(quizAnswers[quizIndex]===undefined){toast('Choose an answer first.');return}if(quizIndex<quizSet.length-1){quizIndex++;renderQuiz()}else showResults()}
function showResults(){let correct=quizSet.filter((q,i)=>quizAnswers[i]===q.a).length,score=Math.round(correct/quizSet.length*100);state.quiz.push({score,correct,total:quizSet.length,date:new Date().toLocaleDateString()});save();app.innerHTML=`<div class="eyebrow">EXAM REPORT</div><h1 class="slide-title">${score>=80?'Excellent work.':score>=60?'Good progress.':'Keep practicing.'}</h1><div class="hero"><div class="result">${score}%</div><p>${correct} correct out of ${quizSet.length} questions.</p><div class="progress"><span style="width:${score}%"></span></div></div>${quizSet.map((q,i)=>`<div class="content-card"><div class="source-label">Question ${i+1} · Slide ${q.s}</div><b>${esc(q.q)}</b><p style="color:${quizAnswers[i]===q.a?'var(--teal)':'var(--red)'}">Your answer: ${esc(q.o[quizAnswers[i]])}</p><p><b>Correct:</b> ${esc(q.o[q.a])}</p><p class="small">${esc(q.e)}</p></div>`).join('')}<button class="primary" onclick="setView('exam')">Back to exam center</button>`}
function workspace(){let notes=Object.entries(state.notes).filter(([k,v])=>v.trim());return `<div class="eyebrow">PERSONAL STUDY WORKSPACE</div><h1 style="font-size:28px;margin:8px 0">Your study space</h1><div class="grid"><div class="stat"><strong>${state.done.length}/33</strong><span>Completed slides</span></div><div class="stat"><strong>${state.bookmarks.length}</strong><span>Saved bookmarks</span></div><div class="stat"><strong>${notes.length}</strong><span>Personal notes</span></div><div class="stat"><strong>${state.quiz.length}</strong><span>Exam attempts</span></div></div><div class="section-head"><div><h2>Bookmarked slides</h2><p>Your saved concepts</p></div></div>${state.bookmarks.length?`<div class="slide-list">${state.bookmarks.map(n=>slideRow(slideBy(n))).join('')}</div>`:'<div class="card small muted">No bookmarks yet. Save a slide using the bookmark button.</div>'}<div class="section-head"><div><h2>Your notes</h2><p>Notes are stored locally on this device</p></div></div>${notes.length?notes.map(([n,v])=>`<div class="content-card"><b>Slide ${n} · ${esc(slideBy(+n).title)}</b><p>${esc(v)}</p><button class="ghost" onclick="openSlide(${n})">Edit note</button></div>`).join(''):'<div class="card small muted">No notes yet.</div>'}<div class="content-card"><h3>Export your study data</h3><p class="small muted">Download bookmarks, completion, quiz history and notes as a JSON backup.</p><button class="secondary" onclick="exportData()">Export backup</button><button class="ghost" onclick="clearProgress()">Reset progress</button></div>`}
function exportData(){let blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='medchem-sulfonamides-progress.json';a.click();URL.revokeObjectURL(a.href)}function clearProgress(){if(confirm('Reset all local progress, bookmarks, quiz history and notes?')){localStorage.removeItem('medchemState');location.reload()}}
function toggleDone(n){state.done=state.done.includes(n)?state.done.filter(x=>x!==n):[...state.done,n];save();render()}function toggleBookmark(n){state.bookmarks=state.bookmarks.includes(n)?state.bookmarks.filter(x=>x!==n):[...state.bookmarks,n];save();render()}function render(){if(activeSlide){app.innerHTML=slideDetail(slideBy(activeSlide));return}app.innerHTML=view==='home'?home():view==='library'?library():view==='studio'?studio():view==='exam'?exam():workspace()}
document.querySelectorAll('.tab').forEach(b=>b.addEventListener('click',()=>setView(b.dataset.view)));document.querySelector('.brand').addEventListener('click',()=>setView('home'));document.getElementById('themeBtn').addEventListener('click',()=>{document.body.classList.toggle('light');state.theme=document.body.classList.contains('light')?'light':'dark';save()});if(state.theme==='light')document.body.classList.add('light');if('serviceWorker'in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').then(()=>document.getElementById('offlineState').textContent='● Offline ready').catch(()=>document.getElementById('offlineState').textContent='● Online'));render();
